    """``exc`` 是否意味着「文件正被别的进程占用」，也就是可以推迟的失败。"""
    if isinstance(exc, PermissionError):
        return True
    return getattr(exc, "winerror", None) in _LOCKED_WINERRORS


def _ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


