    """去掉只读属性：Windows 上只读文件既删不掉，有时也改名不了。"""
    try:
        os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
    except OSError:
        pass


def _remove_quietly(path):
    """尽力删除一个文件，失败不抛异常。"""
    if not path:
        return
    try:
        os.remove(path)
    except OSError:
        _clear_readonly(path)
        try:
            os.remove(path)
        except OSError:
            pass


def _remove_tree(path):
    """尽力删除一棵目录树（含只读文件），失败不抛异常。"""
    try:
        names = os.listdir(path)
    except OSError:
        return
    for name in names:
        full = os.path.join(path, name)
        if os.path.isdir(full) and not os.path.islink(full):
            _remove_tree(full)
        else:
            _remove_quietly(full)
    try:
        os.rmdir(path)
    except OSError:
        _clear_readonly(path)
        try:
            os.rmdir(path)
        except OSError:
            pass


def _read_bytes(path):
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except OSError:
        return None


def _write_bytes(path, blob):
    _ensure_parent(path)
    tmp = path + ".tmp"
    with open(tmp, "wb") as fh:
        fh.write(blob)
    os.replace(tmp, path)


def _move_aside(source, destination):
    """把 ``source`` 改名到 ``destination``（同卷，不复制数据）。

    返回 ``None`` 表示改名成功；返回一个异常对象表示 ``source`` **正被别的
    进程占用**（调用方据此推迟该动作）；其它错误照常抛出。
    """
    _ensure_parent(destination)
    _remove_quietly(destination)  # 上一次事务可能留下的同名备份
    try:
        os.replace(source, destination)
        return None
    except OSError as exc:
        if not is_locked_error(exc):
            raise
        locked = exc
    # 只读属性同样会让 Windows 拒绝改名；去掉属性再试一次，仍然失败才认定
    # 文件被别的进程打开着。
    _clear_readonly(source)
    try:
        os.replace(source, destination)
        return None
    except OSError as exc:
        _remove_quietly(destination)
        if is_locked_error(exc):
            return locked
        raise


def _sweep_temporaries(directory):
    """删掉目录树里遗留的临时文件（``*.winstall-part`` / ``*.winstall-bak``）。"""
    if not os.path.isdir(directory):
        return
    for current, _subdirs, names in os.walk(directory):
        for name in names:
            if name.endswith(TMP_SUFFIX) or name.endswith(BAK_SUFFIX):
                _remove_quietly(os.path.join(current, name))


class _Transaction(object):
    """一次 :func:`apply_transaction` 调用的执行状态与回滚日志。"""

    def __init__(self, plan):
        self.plan = plan
        self.payload = layout.payload_dir(plan.root, plan.product)
        self.rollback_root = os.path.join(
            layout.product_dir(plan.root, plan.product), ROLLBACK_DIRNAME)
        self.manifest_file = manifest.manifest_path(plan.root)
        self.manifest_before = _read_bytes(self.manifest_file)

        self.applied = []
        self.deferred = []
        self._undo = []
        self._manifest_touched = False

    # -- 对外入口 -------------------------------------------------------

    def run(self):
        try:
            for action in self.plan.actions:
                self._execute(action)
            self._commit()
        except _NotDeferrable as failure:
            self._rollback()
            raise ApplyFailed(failure.action, failure.message) from failure.cause
        except BaseException:
            # 意料之外的错误同样要保证现场干净，然后把原异常抛出去。
            self._rollback()
            raise
        self._discard_backups()
        return ApplyResult(self.plan.operation, self.plan.product, self.plan.version,
                           tuple(self.applied), tuple(self.deferred))

    # -- 单个动作 -------------------------------------------------------

    def _execute(self, action):
        kind = action.kind
        if kind == "write":
            self._write(action)
        elif kind == "remove":
            self._remove(action)
        else:
            raise ValueError("unknown action: %r" % (kind,))

    def _write(self, action):
        """把源文件放到目标位置；目标被占用时推迟，其它失败触发回滚。"""
        target = planner.destination(self.plan, action)
        source = action.source

        if os.path.isdir(target):
            # 目标位置被一个同名目录占据：既不能覆盖，也没法推迟。
            raise _NotDeferrable(
                action, "destination is occupied by a directory: %s" % (target,))
        if not source or not os.path.isfile(source):
            raise _NotDeferrable(
                action, "source payload file is missing: %r" % (source,))

        had_target = os.path.exists(target)
        backup = None
        if had_target:
            # 先把旧内容改名让位，回滚时改名回来即可逐字节还原。
            backup = self._backup_path(action.relpath)
            try:
                locked = _move_aside(target, backup)
            except OSError as exc:
                raise _NotDeferrable(
                    action, "cannot replace %s: %s" % (target, exc), exc)
            if locked is not None:
                # 目标被别的进程打开着：旧内容原地不动，等下一次执行。
                self.deferred.append(action.relpath)
                return

        temporary = target + TMP_SUFFIX
        try:
            _ensure_parent(target)
            shutil.copyfile(source, temporary)
        except OSError as exc:
            _remove_quietly(temporary)
            self._put_back(target, backup)
            raise _NotDeferrable(action, "cannot stage %s: %s" % (source, exc), exc)
        try:
            os.replace(temporary, target)
        except OSError as exc:
            _remove_quietly(temporary)
            if self._put_back(target, backup) and is_locked_error(exc):
                self.deferred.append(action.relpath)
                return
            raise _NotDeferrable(
                action, "cannot replace %s: %s" % (target, exc), exc)

        if had_target:
            self._undo.append(("restore", target, backup))
        else:
            self._undo.append(("delete", target, None))
        self.applied.append(action.relpath)

    def _remove(self, action):
        """删除一个旧版本留下的文件；被占用时推迟。"""
        target = planner.destination(self.plan, action)
        if not os.path.isfile(target):
            # 已经不存在（或者是个目录）：无事可做，也不算失败。
            self.applied.append(action.relpath)
            return

        # 先改名到回滚暂存区，失败回滚时还能原样放回；确认成功后再真正删掉。
        backup = self._backup_path(action.relpath)
        try:
            locked = _move_aside(target, backup)
        except OSError as exc:
            raise _NotDeferrable(action, "cannot remove %s: %s" % (target, exc), exc)
        if locked is not None:
            self.deferred.append(action.relpath)
            return

        self._undo.append(("restore", target, backup))
        self.applied.append(action.relpath)

    # -- 提交 / 回滚 ----------------------------------------------------

    def _commit(self):
        """所有动作都处理完了，把结果写进清单。"""
        data = manifest.read_manifest(self.plan.root)
        if self.plan.operation == planner.INSTALL:
            manifest.set_product(data, self.plan.product, self.plan.version,
                                 self.plan.files, self.deferred)
        elif self.deferred:
            # 卸载时仍有文件删不掉：保留条目并记下残留，等下一次执行收尾。
            previous = self.plan.previous or {}
            version = previous.get("version") or self.plan.version
            manifest.set_product(data, self.plan.product, version,
                                 self.deferred, self.deferred)
        else:
            manifest.drop_product(data, self.plan.product)

        self._manifest_touched = True
        try:
            manifest.write_manifest(self.plan.root, data)
        except OSError as exc:
            raise _NotDeferrable(None, "cannot write manifest: %s" % (exc,), exc)

    def _rollback(self):
        """把文件系统与清单恢复到本次事务开始之前的样子。"""
        for kind, target, backup in reversed(self._undo):
            try:
                if kind == "restore":
                    if backup and os.path.exists(backup):
                        _ensure_parent(target)
                        _clear_readonly(target)
                        os.replace(backup, target)
                else:  # "delete"：本次事务新建的文件
                    _remove_quietly(target)
            except OSError:
                # 回滚本身尽力而为，不能让清理动作掩盖真正的失败原因。
                pass
        self._undo = []
        self._restore_manifest()
        self._discard_backups()

    def _restore_manifest(self):
        if not self._manifest_touched:
            return
        self._manifest_touched = False
        try:
            if self.manifest_before is None:
                _remove_quietly(self.manifest_file)  # 本次事务新建的清单
            else:
                _write_bytes(self.manifest_file, self.manifest_before)
        except OSError:
            pass

    def _discard_backups(self):
        """事务收尾：清掉回滚暂存与载荷目录里的临时文件。"""
        _remove_tree(self.rollback_root)
        _sweep_temporaries(self.payload)

    # -- 小工具 ---------------------------------------------------------

    def _backup_path(self, relpath):
        parts = [chunk for chunk in str(relpath).replace("\\", "/").split("/")
                 if chunk not in ("", ".")]
        if not parts:
            parts = ["payload"]
        return os.path.join(self.rollback_root, os.sep.join(parts) + BAK_SUFFIX)

    def _put_back(self, target, backup):
        """把刚才让位的旧内容放回原位；返回旧内容是否确实回到了 ``target``。"""
        if not backup or not os.path.exists(backup):
            return os.path.exists(target)
        try:
            _ensure_parent(target)
            _clear_readonly(target)
            os.replace(backup, target)
        except OSError:
            return os.path.exists(target)
        return True


def apply_transaction(plan):
    """顺序执行 ``plan`` 中的动作，然后更新清单。

    返回 :class:`ApplyResult`。被其它进程占用的目标文件不会被强行替换，
    而是记进 ``deferred`` 与清单的 ``pending_replace``；无法推迟的失败会
    整体回滚并抛出 :class:`~winstall.errors.ApplyFailed`。
    """
    return _Transaction(plan).run()

"""执行计划中的动作，并维护清单。

写入采用「同目录临时文件 + 原子替换」：目标位置要么是旧内容，要么是新内容，
既不会出现半个文件，也不会出现文件暂时消失的窗口。

Windows 上还有两类必须区别对待的失败：

* **目标文件正被别的进程打开**（很常见，不该让整次安装失败）。
  这种失败可以推迟：文件保持**旧内容不动**，相对路径记进
  :attr:`ApplyResult.deferred` 与清单里该产品的 ``pending_replace``，
  其余动作照常执行。占用解除后，对同一份计划再次调用
  :func:`apply_transaction` 即可完成替换，``pending_replace`` 随之清空。

* **无法推迟的失败**（例如目标位置被一个同名目录占据、源载荷丢失）。
  这种失败必须整体回滚：本次已覆盖的文件按字节恢复成旧内容，本次新建的
  文件被删除，清单回到执行前的状态，临时文件全部清理，最后抛出
  :class:`~winstall.errors.ApplyFailed`。

回滚所需的旧内容事先备份到产品目录下的 ``.winstall-rollback``（与载荷同卷）；
无论成功还是失败，事务结束时都会被清掉，载荷目录里不会残留任何临时文件。
"""

import os
import shutil
import stat
from collections import namedtuple

from . import layout, manifest, planner
from .errors import ApplyFailed

ApplyResult = namedtuple("ApplyResult", "operation product version applied deferred")

#: 原子替换用的同目录临时文件后缀。
TMP_SUFFIX = ".winstall-part"
#: 回滚备份文件的后缀（只出现在 ``.winstall-rollback`` 目录里）。
BAK_SUFFIX = ".winstall-bak"
#: 回滚暂存目录名，位于产品目录下、载荷目录之外。
ROLLBACK_DIRNAME = ".winstall-rollback"

# Windows 上「文件正被别的进程使用」表现为这几个错误码：
#   5  ERROR_ACCESS_DENIED      —— 替换 / 删除一个没有共享删除权的打开文件
#   32 ERROR_SHARING_VIOLATION  —— 共享方式冲突
#   33 ERROR_LOCK_VIOLATION     —— 字节范围锁冲突
_LOCKED_WINERRORS = frozenset((5, 32, 33))


class _NotDeferrable(Exception):
    """内部信号：某个动作失败且无法推迟，整次事务必须回滚。"""

    def __init__(self, action, message, cause=None):
        super().__init__(message)
        self.action = action
        self.message = message
        self.cause = cause


def is_locked_error(exc):
    """``exc`` 是否意味着「文件正被别的进程占用」，也就是可以推迟的失败。"""
    if isinstance(exc, PermissionError):
        return True
    return getattr(exc, "winerror", None) in _LOCKED_WINERRORS


def _ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


def _is_readonly(path):
    try:
        return not os.stat(path).st_mode & stat.S_IWRITE
    except OSError:
        return False


def _clear_readonly(path):
    """去掉只读属性：Windows 上只读文件既删不掉也替换不了。"""
    try:
        os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
    except OSError:
        pass


def _set_readonly(path):
    try:
        os.chmod(path, stat.S_IREAD)
    except OSError:
        pass


def _delete_file(path):
    """删除一个文件。

    Windows 上只读文件删不掉，先去掉只读属性再试一次；仍然失败就把属性
    恢复回去并抛出原异常（多半是文件正被别的进程打开着）。
    """
    try:
        os.remove(path)
        return
    except OSError as exc:
        if not is_locked_error(exc) or not _is_readonly(path):
            raise
    _clear_readonly(path)
    try:
        os.remove(path)
    except OSError:
        _set_readonly(path)
        raise


def _remove_quietly(path):
    """尽力删除一个文件，失败不抛异常。"""
    if not path:
        return
    try:
        _delete_file(path)
    except OSError:
        pass


def _remove_tree(path):
    """尽力删除一棵目录树（含只读文件），失败不抛异常。"""
    try:
        names = os.listdir(path)
    except OSError:
        return
    for name in names:
        full = os.path.join(path, name)
        if os.path.isdir(full) and not os.path.islink(full):
            _remove_tree(full)
        else:
            _remove_quietly(full)
    try:
        os.rmdir(path)
    except OSError:
        _clear_readonly(path)
        try:
            os.rmdir(path)
        except OSError:
            pass


def _read_bytes(path):
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except OSError:
        return None


def _write_bytes(path, blob):
    _ensure_parent(path)
    tmp = path + ".tmp"
    with open(tmp, "wb") as fh:
        fh.write(blob)
    os.replace(tmp, path)


def _backup_file(source, destination):
    """把 ``source`` 连内容带属性备份到 ``destination``，供回滚时还原。"""
    _ensure_parent(destination)
    _remove_quietly(destination)  # 上一次事务可能留下的同名备份
    shutil.copyfile(source, destination)
    try:
        shutil.copystat(source, destination)
    except OSError:
        pass  # 属性复制不了不影响按字节回滚


def _replace_file(temporary, target):
    """把临时文件原子替换到 ``target``。

    目标带只读属性时 Windows 会拒绝替换，去掉属性再试一次；仍然失败就把
    属性恢复回去并抛出原异常（说明目标正被别的进程打开着）。
    """
    try:
        os.replace(temporary, target)
        return
    except OSError as exc:
        if not is_locked_error(exc) or not _is_readonly(target):
            raise
    _clear_readonly(target)
    try:
        os.replace(temporary, target)
    except OSError:
        _set_readonly(target)
        raise


def _sweep_temporaries(directory):
    """删掉目录树里遗留的临时文件（``*.winstall-part`` / ``*.winstall-bak``）。"""
    if not os.path.isdir(directory):
        return
    for current, _subdirs, names in os.walk(directory):
        for name in names:
            if name.endswith(TMP_SUFFIX) or name.endswith(BAK_SUFFIX):
                _remove_quietly(os.path.join(current, name))


class _Transaction(object):
    """一次 :func:`apply_transaction` 调用的执行状态与回滚日志。"""

    def __init__(self, plan):
        self.plan = plan
        self.payload = layout.payload_dir(plan.root, plan.product)
        self.rollback_root = os.path.join(
            layout.product_dir(plan.root, plan.product), ROLLBACK_DIRNAME)
        self.manifest_file = manifest.manifest_path(plan.root)
        self.manifest_before = _read_bytes(self.manifest_file)

        self.applied = []
        self.deferred = []
        self._undo = []
        self._manifest_touched = False

    # -- 对外入口 -------------------------------------------------------

    def run(self):
        try:
            for action in self.plan.actions:
                self._execute(action)
            self._commit()
        except _NotDeferrable as failure:
            self._rollback()
            raise ApplyFailed(failure.action, failure.message) from failure.cause
        except BaseException:
            # 意料之外的错误同样要保证现场干净，然后把原异常抛出去。
            self._rollback()
            raise
        self._discard_backups()
        return ApplyResult(self.plan.operation, self.plan.product, self.plan.version,
                           tuple(self.applied), tuple(self.deferred))

    # -- 单个动作 -------------------------------------------------------

    def _execute(self, action):
        kind = action.kind
        if kind == "write":
            self._write(action)
        elif kind == "remove":
            self._remove(action)
        else:
            raise ValueError("unknown action: %r" % (kind,))

    def _write(self, action):
        """把源文件放到目标位置；目标被占用时推迟，其它失败触发回滚。"""
        target = planner.destination(self.plan, action)
        source = action.source

        if os.path.isdir(target):
            # 目标位置被一个同名目录占据：既不能覆盖，也没法推迟。
            raise _NotDeferrable(
                action, "destination is occupied by a directory: %s" % (target,))
        if not source or not os.path.isfile(source):
            raise _NotDeferrable(
                action, "source payload file is missing: %r" % (source,))

        had_target = os.path.exists(target)
        backup = None
        if had_target:
            # 先留一份旧内容，回滚时才能逐字节还原。读不到旧内容通常就是文件
            # 被别的进程独占打开了：这种情况下不去动目标，直接推迟。
            backup = self._backup_path(action.relpath)
            try:
                _backup_file(target, backup)
            except OSError as exc:
                _remove_quietly(backup)
                if is_locked_error(exc):
                    self.deferred.append(action.relpath)
                    return
                raise _NotDeferrable(
                    action, "cannot back up %s: %s" % (target, exc), exc)

        temporary = target + TMP_SUFFIX
        try:
            _ensure_parent(target)
            shutil.copyfile(source, temporary)
        except OSError as exc:
            _remove_quietly(temporary)
            _remove_quietly(backup)
            raise _NotDeferrable(action, "cannot stage %s: %s" % (source, exc), exc)

        try:
            _replace_file(temporary, target)
        except OSError as exc:
            # 原子替换失败说明目标一个字节都没动过，备份也就不需要了。
            _remove_quietly(temporary)
            _remove_quietly(backup)
            if had_target and is_locked_error(exc):
                self.deferred.append(action.relpath)
                return
            raise _NotDeferrable(
                action, "cannot replace %s: %s" % (target, exc), exc)

        if had_target:
            self._undo.append(("restore", target, backup))
        else:
            self._undo.append(("delete", target, None))
        self.applied.append(action.relpath)

    def _remove(self, action):
        """删除一个旧版本留下的文件；被占用时推迟。"""
        target = planner.destination(self.plan, action)
        if not os.path.isfile(target):
            # 已经不存在（或者是个目录）：无事可做，也不算失败。
            self.applied.append(action.relpath)
            return

        # 先备份再删，回滚时才能把它原样放回去。
        backup = self._backup_path(action.relpath)
        try:
            _backup_file(target, backup)
        except OSError as exc:
            _remove_quietly(backup)
            if is_locked_error(exc):
                self.deferred.append(action.relpath)
                return
            raise _NotDeferrable(
                action, "cannot back up %s: %s" % (target, exc), exc)

        try:
            _delete_file(target)
        except OSError as exc:
            _remove_quietly(backup)
            if is_locked_error(exc):
                self.deferred.append(action.relpath)
                return
            raise _NotDeferrable(action, "cannot remove %s: %s" % (target, exc), exc)

        self._undo.append(("restore", target, backup))
        self.applied.append(action.relpath)

    # -- 提交 / 回滚 ----------------------------------------------------

    def _commit(self):
        """所有动作都处理完了，把结果写进清单。"""
        data = manifest.read_manifest(self.plan.root)
        if self.plan.operation == planner.INSTALL:
            manifest.set_product(data, self.plan.product, self.plan.version,
                                 self.plan.files, self.deferred)
        elif self.deferred:
            # 卸载时仍有文件删不掉：保留条目并记下残留，等下一次执行收尾。
            previous = self.plan.previous or {}
            version = previous.get("version") or self.plan.version
            manifest.set_product(data, self.plan.product, version,
                                 self.deferred, self.deferred)
        else:
            manifest.drop_product(data, self.plan.product)

        self._manifest_touched = True
        try:
            manifest.write_manifest(self.plan.root, data)
        except OSError as exc:
            raise _NotDeferrable(None, "cannot write manifest: %s" % (exc,), exc)

    def _rollback(self):
        """把文件系统与清单恢复到本次事务开始之前的样子。"""
        for kind, target, backup in reversed(self._undo):
            try:
                if kind == "restore":
                    if backup and os.path.exists(backup):
                        _ensure_parent(target)
                        _replace_file(backup, target)
                else:  # "delete"：本次事务新建的文件
                    _remove_quietly(target)
            except OSError:
                # 回滚本身尽力而为，不能让清理动作掩盖真正的失败原因。
                pass
        self._undo = []
        self._restore_manifest()
        self._discard_backups()

    def _restore_manifest(self):
        if not self._manifest_touched:
            return
        self._manifest_touched = False
        try:
            if self.manifest_before is None:
                _remove_quietly(self.manifest_file)  # 本次事务新建的清单
            else:
                _write_bytes(self.manifest_file, self.manifest_before)
        except OSError:
            pass

    def _discard_backups(self):
        """事务收尾：清掉回滚暂存与载荷目录里的临时文件。"""
        _remove_tree(self.rollback_root)
        _sweep_temporaries(self.payload)

    # -- 小工具 ---------------------------------------------------------

    def _backup_path(self, relpath):
        parts = [chunk for chunk in str(relpath).replace("\\", "/").split("/")
                 if chunk not in ("", ".")]
        if not parts:
            parts = ["payload"]
        return os.path.join(self.rollback_root, os.sep.join(parts) + BAK_SUFFIX)


def apply_transaction(plan):
    """顺序执行 ``plan`` 中的动作，然后更新清单。

    返回 :class:`ApplyResult`。被其它进程占用的目标文件不会被强行替换，
